    chairs = image_patch.find("chair")
    girls = image_patch.find("girl")

    if not chairs or not girls:
        return image_patch

    girl_chairs = [g for g in girls for c in chairs if g.overlaps_with(*c.bbox())]

    if not girl_chairs:
        return image_patch

    sitting_on = [c for c in chairs if any(g.overlaps_with(*c.bbox()) for g in girl_chairs)]

    if not sitting_on:
        return image_patch

    return sitting_on[0]

