def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    motorcycle_patches = image_patch.find("motorcycle")

    if not motorcycle_patches:
        return image_patch

    brown_motorcycles = [m for m in motorcycle_patches if m.verify_property("motorcycle", "brown")]
    black_motorcycles = [m for m in motorcycle_patches if m.verify_property("motorcycle", "black")]

    if not brown_motorcycles or not black_motorcycles:
        return image_patch

    brown_black_motorcycles = [m for m in brown_motorcycles if m in black_motorcycles]

    if not brown_black_motorcycles:
        return image_patch

    tail_light_patches = image_patch.find("tail light")
    red_tail_lights = [tl for tl in tail_light_patches if tl.verify_property("tail light", "red")]

    if not red_tail_lights:
        return image_patch

    red_tail_light_motorcycles = []
    for mb in brown_black_motorcycles:
        for tl in red_tail_lights:
            if distance(mb, tl) < 10:  # Assuming a threshold of 10 pixels for proximity
                red_tail_light_motorcycles.append(mb)
                break

    if not red_tail_light_motorcycles:
        return image_patch

    return red_tail_light_motorcycles[0]

