modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    table_patches = image_patch.find("table")
    person_patches = image_patch.find("person")

    if not table_patches or len(person_patches) < 2:
        return image_patch

    table = max(table_patches, key=lambda t: t.compute_depth())
    people = sorted(person_patches, key=lambda p: p.compute_depth(), reverse=True)[:2]

    closest_person = min(people, key=lambda p: abs(p.horizontal_center - table.horizontal_center))
    other_person = [p for p in people if p != closest_person][0]

    if closest_person.horizontal_center > table.horizontal_center:
        return closest_person
    elif other_person.horizontal_center > table.horizontal_center:
        return other_person
    else:
        return table

